<?php
require __DIR__ . '/bootstrap.php'; require_login();
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['verify_id'])){try{supabase('PATCH','payments?id=eq.'.rawurlencode($_POST['verify_id']),['status'=>'verified','reviewed_at'=>date('c'),'reviewed_by'=>$_SESSION['user_id']]);$message='Payment verified.';}catch(Throwable $e){$error=$e->getMessage();}}
try{$payments=supabase('GET','payments?select=*,profiles(full_name,art_id)&order=submitted_at.desc');}catch(Throwable $e){$payments=[];$error=$e->getMessage();}
$content='<div class="mb-4"><h2 class="h4">Payments & receipts</h2><p class="text-muted">Verify payment submissions and receipts.</p></div>';if($message)$content.='<div class="alert alert-success">'.e($message).'</div>';if($error)$content.='<div class="alert alert-danger">'.e($error).'</div>';$content.='<div class="card rounded-4 p-3 table-responsive"><table class="table align-middle"><thead><tr><th>User</th><th>Amount</th><th>Receipt path</th><th>Status</th><th></th></tr></thead><tbody>';
foreach($payments as $p){$profile=$p['profiles']??[];$content.='<tr><td>'.e($profile['full_name']??'Unknown').'<small class="d-block text-muted">'.e($profile['art_id']??'').'</small></td><td>₦'.number_format((float)$p['amount'],2).'</td><td>'.e($p['receipt_path']??'Not attached').'</td><td>'.e($p['status']).'</td><td>'.($p['status']==='pending'?'<form method="post"><input type="hidden" name="verify_id" value="'.e($p['id']).'"><button class="btn btn-sm btn-outline-success">Verify</button></form>':'—').'</td></tr>';}$content.='</tbody></table></div>';$title='Payments & receipts';page($title,$content);
